_widthAnimation = Tween<double>(begin: 50, end: 150).animate(
  CurvedAnimation(
    parent: _controller,
    curve: Interval(0.0, 0.50, curve: Curves.ease),
  ),
);

_heightAnimation = Tween<double>(begin: 50, end: 150).animate(
  CurvedAnimation(
    parent: _controller,
    curve: Interval(0.50, 1.0, curve: Curves.ease),
  ),
);
